import glob
import os
from .exceptions import FileNotFound, MultipleMatches


class PathsProvider(object):
    templates_pattern = 'HeatTemplates*'

    def __init__(self, root='site_solution'):
        self.templates_root_dirname = root

    def _return_path(self, matches):
        matches_count = len(matches)
        if matches_count < 1:
            raise FileNotFound
        elif matches_count > 1:
            raise MultipleMatches
        return matches[0]

    def find_templates_archive(self, _dir):
        templates_path = os.path.join(_dir, self.templates_pattern)
        return self._return_path(glob.glob(templates_path))

    def find_templates_root_path(self, _dir):
        templates_path = os.path.join(_dir, self.templates_root_dirname)
        return self._return_path(glob.glob(templates_path))


class TemplatesFinder(object):
    def __init__(self, definition, recognizer):
        self.templates_def = definition
        self.recognizer = recognizer

    def find(self, templates_root):
        """ Given path to root of all templates find concrete templates.
        Name arguments may differ for different templates versions e.g
        5G17, 5G17A. """
        dir_path = self.get_templates_path(templates_root)
        templates_paths = self.recognizer.get_templates_paths(dir_path)
        return templates_paths

    def get_templates_path(self, templates_root):
        return self.templates_def.get_templates_dir(templates_root)


class TemplatesRecognizer(object):
    def __init__(self):
        self._yaml = '.yaml'
        self._env = '.env'
        self.extensions = ('*.yaml', '*.env')

    def get_templates_paths(self, dir_path):
        """ Return list of absolute paths to all files recognized as templates
        in giver directory.

            :dir_path: path to directory
            :returns: list of absolute paths
        """
        paths = []
        for ext in self.extensions:
            p = os.path.join(dir_path, ext)
            paths.extend(glob.glob(p))
        return paths

    def definition_files(self, paths):
        """ Return paths which points to definition files (in NCIR stored
        often as with .yaml extension).

        :paths: list of paths
        :returns: list of paths, subset of paths

        """
        return self._files_with_extension(paths, self._yaml)

    def variable_files(self, paths):
        """ Return paths which points to files containing variables (in NCIR
        stored often as with .env extension).

        :paths: list of paths
        :returns: list of paths, subset of paths

        """
        return self._files_with_extension(paths, self._env)

    def match_variables(self, definition, variables):
        """Takes path to file with definitions (.yaml) and list of variable
        files (.env) files and returns path to env file if one matched.

        :definition: path to file with heat stack definition
        :variables: list of paths to environment files containing variables
        :returns: path to variables file or None

        """
        def get_filename(path):
            name = os.path.basename(path)
            return name.rsplit('.', 1)[0]

        base_definition = get_filename(definition)

        for var_path in variables:
            base_variable = get_filename(var_path)
            if base_definition == base_variable:
                return var_path

    def _files_with_extension(self, paths, extension):
        return [p for p in paths if p.endswith(extension)]
